import csv

power_ts_id = "42493d5e-d7c8-5e7c-b100-a81e5d773b79"
occupancy_ts_id = "26776421-83f2-518b-9716-873fcaa13a04"
target_date = "2018-07-23"

power_values = {}
occ_values = {}

with open(VALUES_CSV, 'r') as f:
    reader = csv.reader(f)
    for row in reader:
        ts_id, timestamp, value = row
        if timestamp.startswith(target_date):
            if ts_id == power_ts_id:
                power_values[timestamp] = float(value)
            elif ts_id == occupancy_ts_id:
                occ_values[timestamp] = float(value)

count = 0
timestamps = sorted(list(set(power_values.keys()) | set(occ_values.keys())))
for ts in timestamps:
    p = power_values.get(ts)
    o = occ_values.get(ts)
    if p is not None and o is not None:
        if p > 1 and o == 0:
            count += 1

print(f"Count: {count}")
